select aj1_0.id,aj1_0.work_id,aj1_0.batch_id,aj1_0.job_type,aj1_0.analysis_mode,aj1_0.review_mode,aj1_0.status,aj1_0.journal_status,aj1_0.automatic_applied_at,aj1_0.source_kind,e1_0.id,aj1_0.source_episode_no,e1_0.episode_no,ssb1_0.id,ssb1_0.original_filename,ssbr1_0.id,ssbr1_0.revision_no,aj1_0.source_content_hash,ssbr1_0.reference_time_kind,ssbr1_0.reference_episode_no,aj1_0.character_comparison_input_hash,case when aj1_0.source_kind='SETTING_BOOK' then case when ssb1_0.id is not null and ssbr1_0.id is not null and ssb1_0.archived_at is null and ssb1_0.current_setting_book_revision_id=ssbr1_0.id and aj1_0.source_content_hash is not distinct from ssbr1_0.content_hash and aj1_0.source_content_s3_key is not distinct from ssbr1_0.content_s3_key and aj1_0.source_content_s3_version is not distinct from ssbr1_0.content_s3_version then true else false end else case when aj1_0.analysis_mode<>'ORDERED_PROVISIONAL' or (e1_0.id is not null and aj1_0.source_episode_no is not distinct from e1_0.episode_no and e1_0.status<>'ARCHIVED' and aj1_0.source_content_hash is not distinct from e1_0.content_hash and aj1_0.source_content_s3_key is not distinct from e1_0.content_s3_key and aj1_0.source_content_s3_version is not distinct from e1_0.content_s3_version) then true else false end end,case when not exists(select aj2_0.id from analysis_jobs aj2_0 where aj2_0.source_setting_book_id=ssb1_0.id and aj2_0.job_type='SETTING_EXTRACTION' and (aj2_0.created_at>aj1_0.created_at or (aj2_0.created_at=aj1_0.created_at and aj2_0.id>aj1_0.id))) then true else false end from analysis_jobs aj1_0 left join episodes e1_0 on e1_0.id=aj1_0.episode_id left join upload_files ssb1_0 on ssb1_0.id=aj1_0.source_setting_book_id left join setting_book_revisions ssbr1_0 on ssbr1_0.id=aj1_0.source_setting_book_revision_id where aj1_0.id in ('1735c13c-3323-59e3-bb76-0b84b1af4e55','8b957cb4-42e6-52f9-8dd2-5e702289e7d4','fada7e34-850e-556e-a41c-9470e8eaff4a','ae143e43-80d9-5492-8229-29a55de24c31','a2707297-ac05-5854